evel"]=1},["steady_form"]={["name"]="스테디 폼",["description"]="자신의 최종 주사위 최솟값을 4로 제한한다.",["maxLevel"]=1},["read_the_play"]={["name"]="리드 더 플레이",["description"]="상대의 이번 행동을 방어로 강제한다.",["maxLevel"]=1},["reset_rhythm"]={["name"]="리듬 리셋",["description"]="자신에게 미리 부여된 흔들림 상태를 하나 제거한다.",["maxLevel"]=1},["breathing_control"]={["name"]="호흡 조절",["description"]="숨고르기의 남은 지속시간을 2턴 줄인다.",["maxLevel"]=1},["reserve_plan"]={["name"]="리저브 플랜",["description"]="다음에 사용할 액티브 스킬의 STA 비용을 5 줄인다.",["maxLevel"]=1},["sideline_coaching"]={["name"]="사이드라인 코칭",["description"]="파워 드라이브의 쿨다운을 2 줄이고 사용 횟수를 1 늘린다.",["maxLevel"]=1},["shaking_feint"]={["name"]="셰이킹 페인트",["description"]="상대에게 2턴 흔들림을 부여한다. 다음 턴부터 최종 주사위가 최대 3이다.",["maxLevel"]=1},["open_guard"]={["name"]="오픈 가드",["description"]="상대에게 2턴 노출을 부여한다. 다음 턴부터 받는 HP 피해가 1.2배다.",["maxLevel"]=1},["focused_guard"]={["name"]="포커스드 가드",["description"]="자신에게 2턴 집중을 부여한다. 다음 턴부터 최종 주사위가 최소 3이다.",["maxLevel"]=1},["purge_negative"]={["name"]="네거티브 퍼지",["description"]="결과 적용 후 가장 오래된 제거 가능 디버프 하나를 정화한다.",["maxLevel"]=1},["stored_momentum"]={["name"]="스토어드 모멘텀",["description"]="3턴 안의 다음 주사위 승리 1회에 상대 BRK를 8 추가 축적한다.",["maxLevel"]=1},["recovery_echo"]={["name"]="리커버리 에코",["description"]="이번 결과와 다음 2턴의 결과 적용 후 HP를 3씩 회복하는 예약 효과를 둔다.",["maxLevel"]=1},["measured_strike"]={["name"]="메저드 스트라이크",["description"]="레벨에 따라 공격 HP 피해 배율이 성장한다.",["maxLevel"]=3},["growth_focus"]={["name"]="그로스 포커스",["description"]="레벨에 따라 지속시간과 다음 턴 주사위 최솟값이 성장한다.",["maxLevel"]=3},["banked_pressure"]={["name"]="뱅크드 프레셔",["description"]="레벨에 따라 다음 승리 예약의 만료와 추가 BRK가 성장한다.",["maxLevel"]=3}}
local function cost(o) return o and o.level+1 or 2 end
function M.render(s)
  local parts={'<p>강화 자원 <strong>'..s.player.trainingPoints..'</strong> · 훈련은 시간을 소비하지 않습니다.</p>'}
  local ids={}; for _,o in ipairs(s.player.skills) do ids[#ids+1]=o.id end
  for _,id in ipairs(P.growthSkills) do if not P.contains(ids,id) then ids[#ids+1]=id end end
  for _,id in ipairs(ids) do
    local d=P.skills[id]; local o=P.owned(s,id); local c=cost(o)
    local reason=P.blocked(s)
    if not reason and o and o.level>=d.maxLevel then reason='최대 레벨입니다.' end
    if not reason and s.player.trainingPoints<c then reason='강화 자원이 부족합니다.' end
    local maximum=o and o.level>=d.maxLevel
    local label=maximum and ('Lv.'..o.level..' · 최대 레벨') or (o and ('Lv.'..o.level..' → '..(o.level+1)) or '신규 습득 · Lv.1')
    parts[#parts+1]=P.card(d.name,'<p>'..P.esc(d.description)..'</p><p>'..label..(maximum and '' or ' · 비용 '..c)..'</p>'..P.button(s,'upgrade',o and '강화' or '습득',id,reason))
  end
  parts[#parts+1]=P.returnButton(s)
  return P.panel(s,'트레이닝',table.concat(parts))
end
function M.handle(id,s,action,value)
  if action=='back' then s.screen='hub'; return true end
  local why=P.blocked(s); if why then return false,why end
  local d=P.skills[value]; local o=P.owned(s,value)
  if action~='upgrade' or not d or (not o and not P.contains(P.growthSkills,value)) then return false,'훈련할 수 없는 스킬입니다.' end
  if o and o.level>=d.maxLevel then return false,'최대 레벨입니다.' end
  local c=cost(o); if s.player.trainingPoints<c then return false,'강화 자원이 부족합니다.' end
  s.player.trainingPoints=s.player.trainingPoints-c
  if o then o.level=o.level+1 else s.player.skills[#s.player.skills+1]={id=value,level=1} end
  s.notice=d.name..' '..(o and ('Lv.'..o.level..' 강화 완료') or '습득 완료 · 경기 정비에서 장착하세요.')
  return true
end

-- The host dispatches a button to every enabled module. Only its owner acts.
local function buttonHandler(id,code)
  if type(code)~='string' then return end
  local owner,rev,action,value=code:match('^pa;([a-z]+);(%d+);([a-z_]+);(.*)$')
  if owner~=P.module then return end
  local s,why=P.load(id); if not s then P.notice(id,why); return end
  if s.revision~=tonumber(rev) then P.notice(id,'오래된 버튼입니다. 현재 화면에서 다시 선택해 주세요.'); P.refresh(id); return end
  if not M.owns(s) then return end
  local expected=s.revision; s=P.copy(s); s.notice=nil
  local safe,ok,msg,effect=pcall(M.handle,id,s,action,value)
  if not safe then P.notice(id,'처리에 실패했습니다. 기존 상태는 보존됩니다.'); if log then log(tostring(ok)) end; return end
  if not ok then if msg then P.notice(id,msg) end; return end
  local committed,err=P.commit(id,s,expected)
  if not committed then P.notice(id,err); return end
  if effect then effect(id) end
  P.refresh(id)
end
onButtonClick=async and async(buttonHandler) or buttonHandler
listenEdit('editDisplay',function(id,data,meta)
  data=P.strip(data)
  if meta and meta.index~=nil and meta.index~=getChatLength(id)-1 then return data end
  local s,why=P.load(id)
  if not s then return P.module=='hub' and data..'<p class="pa-notice">'..P.esc(why)..'</p>' or data end
  if not M.owns(s) then return data end
  return data..P.scope(M.render(s))
end)
if not M.owns then M.owns=function(s) return s.screen==P.module end end
if M.start then onStart=async and async(M.start) or M.start end
if M.output then onOutput=async and async(M.output) or M.output end
if M.request then listenEdit('editRequest',M.request) end
if PRIMAL_APEX_TEST then PA_TEST={P=P,M=M} end
